-- ══════════════════════════════════════════════════════
-- EXPERTO 1 (101-120): CONTAR.SI, Y/O con SI, ABS, REDONDEAR
-- ══════════════════════════════════════════════════════

(101, 'Experto 1', 'CONTAR.SI', 'Contar una categoría', 'Cuenta cuántas veces aparece "Laptop" en B2:B10 en la celda D2.', '=CONTAR.SI(B2:B10,"Laptop")', '=COUNTIF(B2:B10,"Laptop")', 'D2', 46),
(102, 'Experto 1', 'CONTAR.SI', 'Contar aprobados', 'Cuenta cuántos valores de C2:C9 son mayores o iguales a 70 en D3.', '=CONTAR.SI(C2:C9,">=70")', '=COUNTIF(C2:C9,">=70")', 'D3', 46),
(103, 'Experto 1', 'CONTAR.SI', 'Región norte', 'Cuenta cuántas veces aparece "Norte" en A2:A10 en D4.', '=CONTAR.SI(A2:A10,"Norte")', '=COUNTIF(A2:A10,"Norte")', 'D4', 46),
(104, 'Experto 1', 'CONTAR.SI', 'Elementos bajo mínimo', 'Cuenta cuántos valores de D2:D8 son menores a 50 en D5.', '=CONTAR.SI(D2:D8,"<50")', '=COUNTIF(D2:D8,"<50")', 'D5', 47),
(105, 'Experto 1', 'SI + Y', 'Doble condición', 'Si B2 es mayor o igual a 70 Y C2 es mayor o igual a 70, muestra "Aprobado"; si no "Reforzar" en E2.', '=SI(Y(B2>=70,C2>=70),"Aprobado","Reforzar")', '=SI(Y(B2>=70;C2>=70),"Aprobado","Reforzar")', 'E2', 47),
(106, 'Experto 1', 'SI + Y', 'Stock y precio', 'Si C3 es mayor que 10 Y D3 es menor que 500, muestra "Comprar"; si no "Esperar" en E3.', '=SI(Y(C3>10,D3<500),"Comprar","Esperar")', NULL, 'E3', 47),
(107, 'Experto 1', 'SI + O', 'Alerta doble', 'Si B4 es menor a 50 O C4 es menor a 50, muestra "Alerta"; si no "Normal" en E4.', '=SI(O(B4<50,C4<50),"Alerta","Normal")', NULL, 'E4', 48),
(108, 'Experto 1', 'SI + O', 'Prioridad de atención', 'Si D2 es mayor que 1000 O E2 es igual a "Urgente", muestra "Prioridad"; si no "Regular" en F2.', '=SI(O(D2>1000,E2="Urgente"),"Prioridad","Regular")', NULL, 'F2', 48),
(109, 'Experto 1', 'ABS', 'Diferencia absoluta', 'Calcula la diferencia absoluta entre B2 y C2 en D2.', '=ABS(B2-C2)', NULL, 'D2', 48),
(110, 'Experto 1', 'ABS', 'Desviación del objetivo', 'Calcula el valor absoluto de D3 menos 500 en E3.', '=ABS(D3-500)', NULL, 'E3', 49),
(111, 'Experto 1', 'REDONDEAR', 'Redondeo a enteros', 'Redondea el valor de B4/C4 a 0 decimales en D4.', '=REDONDEAR(B4/C4,0)', '=ROUND(B4/C4,0)', 'D4', 49),
(112, 'Experto 1', 'REDONDEAR', 'Redondeo a 2 decimales', 'Redondea el promedio de B2:B6 a 2 decimales en F2.', '=REDONDEAR(PROMEDIO(B2:B6),2)', '=ROUND(PROMEDIO(B2:B6),2)||=REDONDEAR(AVERAGE(B2:B6),2)', 'F2', 49),
(113, 'Experto 1', 'SI + Y', 'Triple filtro', 'Si B5 es mayor o igual a 60 Y C5 es mayor o igual a 60 Y D5 es mayor o igual a 60, muestra "Aprueba"; si no "Repite" en E5.', '=SI(Y(B5>=60,C5>=60,D5>=60),"Aprueba","Repite")', NULL, 'E5', 50),
(114, 'Experto 1', 'CONTAR.SI', 'Contar texto exacto', 'Cuenta cuántas veces aparece "Activo" en E2:E10 en F3.', '=CONTAR.SI(E2:E10,"Activo")', '=COUNTIF(E2:E10,"Activo")', 'F3', 50),
(115, 'Experto 1', 'REDONDEAR', 'Precio redondeado', 'Redondea D2*1.16 a 2 decimales en E2.', '=REDONDEAR(D2*1.16,2)', '=ROUND(D2*1.16,2)', 'E2', 50),
(116, 'Experto 1', 'SI + O', 'Zona conflictiva', 'Si A2 es "Norte" O A2 es "Sur", muestra "Nacional"; si no "Internacional" en F2.', '=SI(O(A2="Norte",A2="Sur"),"Nacional","Internacional")', NULL, 'F2', 51),
(117, 'Experto 1', 'ABS', 'Error de estimación', 'Calcula ABS de la diferencia entre PROMEDIO(B2:B6) y C2 en D2.', '=ABS(PROMEDIO(B2:B6)-C2)', NULL, 'D2', 51),
(118, 'Experto 1', 'CONTAR.SI', 'Contar valores altos', 'Cuenta cuántos valores de B2:B10 son mayores a 500 en C10.', '=CONTAR.SI(B2:B10,">500")', '=COUNTIF(B2:B10,">500")', 'C10', 51),
(119, 'Experto 1', 'SI + Y', 'Bono especial', 'Si D2 es mayor que 1000 Y CONTAR.SI(A2:A8,"Norte") es mayor que 2, muestra "Bono"; si no "Sin bono" en F4.', '=SI(Y(D2>1000,CONTAR.SI(A2:A8,"Norte")>2),"Bono","Sin bono")', NULL, 'F4', 52),
(120, 'Experto 1', 'REDONDEAR', 'Ratio redondeado', 'Redondea SUMA(B2:B6)/CONTAR(B2:B6) a 1 decimal en F5.', '=REDONDEAR(SUMA(B2:B6)/CONTAR(B2:B6),1)', '=ROUND(SUMA(B2:B6)/CONTAR(B2:B6),1)||=REDONDEAR(PROMEDIO(B2:B6),1)', 'F5', 52),

-- ══════════════════════════════════════════════════════
-- EXPERTO 2 (121-140): CONCATENAR, TEXTO, IZQUIERDA, DERECHA, LARGO
-- ══════════════════════════════════════════════════════

(121, 'Experto 2', 'CONCATENAR', 'Unir nombre y apellido', 'Une A2 y B2 separados por un espacio en C2.', '=CONCATENAR(A2," ",B2)', '=CONCAT(A2," ",B2)||=A2&" "&B2', 'C2', 53),
(122, 'Experto 2', 'CONCATENAR', 'Código compuesto', 'Une A3 con un guion y B3 en C3.', '=CONCATENAR(A3,"-",B3)', '=CONCAT(A3,"-",B3)||=A3&"-"&B3', 'C3', 53),
(123, 'Experto 2', 'CONCATENAR', 'Etiqueta de producto', 'Une "Prod-" con el valor de A4 en C4.', '=CONCATENAR("Prod-",A4)', '=CONCAT("Prod-",A4)||="Prod-"&A4', 'C4', 53),
(124, 'Experto 2', 'MAYUSC', 'Texto en mayúsculas', 'Convierte el texto de A2 a mayúsculas en B2.', '=MAYUSC(A2)', '=UPPER(A2)', 'B2', 54),
(125, 'Experto 2', 'MINUSC', 'Texto en minúsculas', 'Convierte el texto de A3 a minúsculas en B3.', '=MINUSC(A3)', '=LOWER(A3)', 'B3', 54),
(126, 'Experto 2', 'LARGO', 'Longitud de texto', 'Calcula la cantidad de caracteres de A2 en B2.', '=LARGO(A2)', '=LEN(A2)', 'B2', 54),
(127, 'Experto 2', 'IZQUIERDA', 'Primeros 3 caracteres', 'Extrae los primeros 3 caracteres de A2 en B2.', '=IZQUIERDA(A2,3)', '=LEFT(A2,3)', 'B2', 55),
(128, 'Experto 2', 'DERECHA', 'Últimos 4 caracteres', 'Extrae los últimos 4 caracteres de A3 en B3.', '=DERECHA(A3,4)', '=RIGHT(A3,4)', 'B3', 55),
(129, 'Experto 2', 'MED', 'Caracteres del medio', 'Extrae 3 caracteres de A4 empezando en la posición 2 en B4.', '=MED(A4,2,3)', '=MID(A4,2,3)||=EXTRAE(A4,2,3)', 'B4', 55),
(130, 'Experto 2', 'CONCATENAR', 'Saludo personalizado', 'Une "Hola, " con A2 y " - Bienvenido" en D2.', '=CONCATENAR("Hola, ",A2," - Bienvenido")', '=CONCAT("Hola, ",A2," - Bienvenido")||="Hola, "&A2&" - Bienvenido"', 'D2', 56),
(131, 'Experto 2', 'IZQUIERDA', 'Código de área', 'Extrae los primeros 2 caracteres de B2 en C2.', '=IZQUIERDA(B2,2)', '=LEFT(B2,2)', 'C2', 56),
(132, 'Experto 2', 'LARGO', 'Validar longitud', 'Si LARGO de A2 es mayor que 10, muestra "Largo"; si no "Corto" en C3.', '=SI(LARGO(A2)>10,"Largo","Corto")', '=SI(LEN(A2)>10,"Largo","Corto")', 'C3', 56),
(133, 'Experto 2', 'CONCATENAR', 'Informe combinado', 'Une A2 con ": " y el valor de B2 con " unidades" en D3.', '=CONCATENAR(A2,": ",B2," unidades")', '=CONCAT(A2,": ",B2," unidades")||=A2&": "&B2&" unidades"', 'D3', 57),
(134, 'Experto 2', 'NOMPROPIO', 'Capitalizar nombre', 'Convierte el texto de A2 a formato de nombre propio en B2.', '=NOMPROPIO(A2)', '=PROPER(A2)', 'B2', 57),
(135, 'Experto 2', 'SUSTITUIR', 'Reemplazar texto', 'Sustituye "viejo" por "nuevo" en A2 y muestra el resultado en B2.', '=SUSTITUIR(A2,"viejo","nuevo")', '=SUBSTITUTE(A2,"viejo","nuevo")', 'B2', 57),
(136, 'Experto 2', 'ENCONTRAR', 'Posición de caracter', 'Encuentra la posición de "@" en A2 en B2.', '=ENCONTRAR("@",A2)', '=FIND("@",A2)', 'B2', 58),
(137, 'Experto 2', 'IZQUIERDA + ENCONTRAR', 'Extraer usuario de email', 'Extrae todo antes del "@" en A2 en B2.', '=IZQUIERDA(A2,ENCONTRAR("@",A2)-1)', '=LEFT(A2,FIND("@",A2)-1)', 'B2', 58),
(138, 'Experto 2', 'DERECHA + LARGO', 'Dominio de email', 'Extrae todo después del "@" en A2 en B2.', '=DERECHA(A2,LARGO(A2)-ENCONTRAR("@",A2))', '=RIGHT(A2,LEN(A2)-FIND("@",A2))', 'B2', 58),
(139, 'Experto 2', 'CONCATENAR', 'Código con IZQUIERDA', 'Une los 3 primeros caracteres de A2 con "-" y B2 en C2.', '=CONCATENAR(IZQUIERDA(A2,3),"-",B2)', '=CONCAT(IZQUIERDA(A2,3),"-",B2)||=IZQUIERDA(A2,3)&"-"&B2||=CONCAT(LEFT(A2,3),"-",B2)', 'C2', 59),
(140, 'Experto 2', 'LARGO + SI', 'Validar código', 'Si LARGO de A3 es igual a 5, muestra "Válido"; si no "Inválido" en C3.', '=SI(LARGO(A3)=5,"Válido","Inválido")', '=SI(LEN(A3)=5,"Válido","Inválido")', 'C3', 59),

