(141, 'Experto 3', 'COINCIDIR', 'Encontrar posición', 'Encuentra la posición de "P400" en A2:A10 con coincidencia exacta en G2.', '=COINCIDIR("P400",A2:A10,0)', '=MATCH("P400",A2:A10,0)', 'G2', 60),
(142, 'Experto 3', 'INDICE', 'Valor por posición', 'Devuelve el valor de la fila 3 de B2:B10 en G3.', '=INDICE(B2:B10,3)', '=INDEX(B2:B10,3)', 'G3', 60),
(143, 'Experto 3', 'INDICE + COINCIDIR', 'Búsqueda flexible', 'Usa INDICE y COINCIDIR para buscar "P400" en A2:A10 y devolver B2:B10 en G4.', '=INDICE(B2:B10,COINCIDIR("P400",A2:A10,0))', '=INDEX(B2:B10,MATCH("P400",A2:A10,0))', 'G4', 60),
(144, 'Experto 3', 'INDICE + COINCIDIR', 'Precio por nombre', 'Busca "Monitor" en B2:B10 y devuelve el precio de D2:D10 en G5.', '=INDICE(D2:D10,COINCIDIR("Monitor",B2:B10,0))', '=INDEX(D2:D10,MATCH("Monitor",B2:B10,0))', 'G5', 61),
(145, 'Experto 3', 'INDICE + COINCIDIR', 'Stock por código', 'Busca H2 en A2:A10 y devuelve E2:E10 en I2.', '=INDICE(E2:E10,COINCIDIR(H2,A2:A10,0))', '=INDEX(E2:E10,MATCH(H2,A2:A10,0))', 'I2', 61),
(146, 'Experto 3', 'SI.CONJUNTO', 'Clasificación por nota', 'Si B2 es mayor o igual a 90 muestra "Excelente", si es mayor o igual a 70 "Bueno", si no "Reforzar" en E2.', '=SI.CONJUNTO(B2>=90,"Excelente",B2>=70,"Bueno",VERDADERO,"Reforzar")', '=IFS(B2>=90,"Excelente",B2>=70,"Bueno",TRUE,"Reforzar")', 'E2', 61),
(147, 'Experto 3', 'SI.CONJUNTO', 'Nivel de stock', 'Si C2 es mayor que 50 muestra "Alto", si es mayor que 20 "Medio", si no "Bajo" en E3.', '=SI.CONJUNTO(C2>50,"Alto",C2>20,"Medio",VERDADERO,"Bajo")', '=IFS(C2>50,"Alto",C2>20,"Medio",TRUE,"Bajo")', 'E3', 62),
(148, 'Experto 3', 'SI.CONJUNTO', 'Rango de precio', 'Si D3 es mayor que 800 muestra "Premium", si es mayor que 300 "Estándar", si no "Económico" en E4.', '=SI.CONJUNTO(D3>800,"Premium",D3>300,"Estándar",VERDADERO,"Económico")', '=IFS(D3>800,"Premium",D3>300,"Estándar",TRUE,"Económico")', 'E4', 62),
(149, 'Experto 3', 'INDICE + COINCIDIR', 'Responsable del producto', 'Busca "Impresora" en B2:B10 y devuelve F2:F10 en G6.', '=INDICE(F2:F10,COINCIDIR("Impresora",B2:B10,0))', '=INDEX(F2:F10,MATCH("Impresora",B2:B10,0))', 'G6', 62),
(150, 'Experto 3', 'INDICE + COINCIDIR', 'Búsqueda protegida', 'Usa SI.ERROR con INDICE+COINCIDIR para buscar H2 en A2:A10 y devolver C2:C10 o "No existe" en I3.', '=SI.ERROR(INDICE(C2:C10,COINCIDIR(H2,A2:A10,0)),"No existe")', '=SI.ERROR(INDEX(C2:C10,MATCH(H2,A2:A10,0)),"No existe")||=IFERROR(INDEX(C2:C10,MATCH(H2,A2:A10,0)),"No existe")', 'I3', 63),
(151, 'Experto 3', 'SI.CONJUNTO', 'Prioridad de soporte', 'Si D2 es mayor que 100 muestra "Crítico", si es mayor que 50 "Alto", si es mayor que 20 "Medio", si no "Bajo" en E5.', '=SI.CONJUNTO(D2>100,"Crítico",D2>50,"Alto",D2>20,"Medio",VERDADERO,"Bajo")', '=IFS(D2>100,"Crítico",D2>50,"Alto",D2>20,"Medio",TRUE,"Bajo")', 'E5', 63),
(152, 'Experto 3', 'COINCIDIR', 'Posición del máximo', 'Encuentra la posición del valor máximo de B2:B10 en G2.', '=COINCIDIR(MAX(B2:B10),B2:B10,0)', '=MATCH(MAX(B2:B10),B2:B10,0)', 'G2', 63),
(153, 'Experto 3', 'INDICE + COINCIDIR', 'Nombre del mejor', 'Devuelve el nombre de A2:A10 que corresponde al valor máximo de B2:B10 en G3.', '=INDICE(A2:A10,COINCIDIR(MAX(B2:B10),B2:B10,0))', '=INDEX(A2:A10,MATCH(MAX(B2:B10),B2:B10,0))', 'G3', 64),
(154, 'Experto 3', 'INDICE + COINCIDIR', 'Producto más barato', 'Devuelve el nombre de B2:B10 del producto con precio mínimo en D2:D10 en G4.', '=INDICE(B2:B10,COINCIDIR(MIN(D2:D10),D2:D10,0))', '=INDEX(B2:B10,MATCH(MIN(D2:D10),D2:D10,0))', 'G4', 64),
(155, 'Experto 3', 'SI.CONJUNTO', 'Descuento escalonado', 'Si B2 es mayor que 1000 muestra 15, si es mayor que 500 muestra 10, si es mayor que 100 muestra 5, si no 0 en C2.', '=SI.CONJUNTO(B2>1000,15,B2>500,10,B2>100,5,VERDADERO,0)', '=IFS(B2>1000,15,B2>500,10,B2>100,5,TRUE,0)', 'C2', 64),
(156, 'Experto 3', 'INDICE + COINCIDIR', 'Búsqueda bidireccional', 'Busca H2 en A2:A10 y devuelve la columna D2:D10 en I4.', '=INDICE(D2:D10,COINCIDIR(H2,A2:A10,0))', '=INDEX(D2:D10,MATCH(H2,A2:A10,0))', 'I4', 65),
(157, 'Experto 3', 'SI.CONJUNTO', 'Evaluación completa', 'Si B3 es mayor o igual a 90 muestra "A", si es mayor o igual a 80 "B", si es mayor o igual a 70 "C", si no "D" en E3.', '=SI.CONJUNTO(B3>=90,"A",B3>=80,"B",B3>=70,"C",VERDADERO,"D")', '=IFS(B3>=90,"A",B3>=80,"B",B3>=70,"C",TRUE,"D")', 'E3', 65),
(158, 'Experto 3', 'INDICE + COINCIDIR', 'Categoría del mínimo', 'Devuelve la categoría de C2:C10 del producto con menor stock en E2:E10 en G5.', '=INDICE(C2:C10,COINCIDIR(MIN(E2:E10),E2:E10,0))', '=INDEX(C2:C10,MATCH(MIN(E2:E10),E2:E10,0))', 'G5', 65),
(159, 'Experto 3', 'COINCIDIR', 'Posición exacta', 'Encuentra la posición de H3 en A2:A10 con coincidencia exacta en I5.', '=COINCIDIR(H3,A2:A10,0)', '=MATCH(H3,A2:A10,0)', 'I5', 66),
(160, 'Experto 3', 'INDICE + COINCIDIR', 'Doble referencia', 'Usa SI.ERROR con INDICE+COINCIDIR para buscar I2 en B2:B10 y devolver F2:F10 o "N/D" en I2.', '=SI.ERROR(INDICE(F2:F10,COINCIDIR(I2,B2:B10,0)),"N/D")', '=SI.ERROR(INDEX(F2:F10,MATCH(I2,B2:B10,0)),"N/D")||=IFERROR(INDEX(F2:F10,MATCH(I2,B2:B10,0)),"N/D")', 'I2', 66),

