(168, 'Experto 4', 'CONTAR.SI.CONJUNTO', 'Productos caros y con stock', 'Cuenta donde D2:D10 sea mayor o igual a 300 Y E2:E10 sea mayor que 10 en G4.', '=CONTAR.SI.CONJUNTO(D2:D10,">=300",E2:E10,">10")', '=COUNTIFS(D2:D10,">=300",E2:E10,">10")', 'G4', 69),
(169, 'Experto 4', 'SUMAR.SI.CONJUNTO', 'Total accesorios baratos', 'Suma D2:D10 donde C2:C10 sea "Accesorios" Y D2:D10 sea menor que 100 en G5.', '=SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Accesorios",D2:D10,"<100")', '=SUMIFS(D2:D10,C2:C10,"Accesorios",D2:D10,"<100")', 'G5', 69),
