(172, 'Experto 4', 'CONTAR.SI.CONJUNTO', 'Filtro con texto parcial', 'Cuenta donde B2:B10 sea "Laptop" Y A2:A10 no sea "P100" en G3.', '=CONTAR.SI.CONJUNTO(B2:B10,"Laptop",A2:A10,"<>P100")', '=COUNTIFS(B2:B10,"Laptop",A2:A10,"<>P100")', 'G3', 70),
(173, 'Experto 4', 'SUMAR.SI.CONJUNTO', 'Suma condicional premium', 'Suma D2:D10 donde D2:D10 sea mayor que 500 Y E2:E10 sea menor que 20 en G4.', '=SUMAR.SI.CONJUNTO(D2:D10,D2:D10,">500",E2:E10,"<20")', '=SUMIFS(D2:D10,D2:D10,">500",E2:E10,"<20")', 'G4', 71),
(174, 'Experto 4', 'CONTAR.SI.CONJUNTO', 'Contar redes con stock', 'Cuenta donde C2:C10 sea "Redes" Y E2:E10 sea mayor que 0 en G5.', '=CONTAR.SI.CONJUNTO(C2:C10,"Redes",E2:E10,">0")', '=COUNTIFS(C2:C10,"Redes",E2:E10,">0")', 'G5', 71),
(175, 'Experto 4', 'SUMAR.SI.CONJUNTO', 'Total multimedia caro', 'Suma D2:D10 donde C2:C10 sea "Multimedia" Y D2:D10 sea mayor o igual a 400 en G6.', '=SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Multimedia",D2:D10,">=400")', '=SUMIFS(D2:D10,C2:C10,"Multimedia",D2:D10,">=400")', 'G6', 71),
(176, 'Experto 4', 'SI + SUMAR.SI.CONJUNTO', 'Meta regional', 'Si SUMAR.SI.CONJUNTO de D2:D10 donde A2:A10 sea "Norte" Y C2:C10 sea "Tecnología" supera 500, muestra "Meta"; si no "Falta" en I2.', '=SI(SUMAR.SI.CONJUNTO(D2:D10,A2:A10,"Norte",C2:C10,"Tecnología")>500,"Meta","Falta")', NULL, 'I2', 72),
(177, 'Experto 4', 'SI + CONTAR.SI.CONJUNTO', 'Verificar cobertura', 'Si CONTAR.SI.CONJUNTO de A2:A10 "Activo" Y B2:B10 mayor que 300 es mayor o igual a 3, muestra "Cubierto"; si no "Insuficiente" en I3.', '=SI(CONTAR.SI.CONJUNTO(A2:A10,"Activo",B2:B10,">300")>=3,"Cubierto","Insuficiente")', NULL, 'I3', 72),
(178, 'Experto 4', 'SUMAR.SI.CONJUNTO', 'Diferencia de zonas', 'Resta SUMAR.SI.CONJUNTO de D2:D10 con A2:A10 "Sur" a SUMAR.SI.CONJUNTO con A2:A10 "Norte" en I4.', '=SUMAR.SI.CONJUNTO(D2:D10,A2:A10,"Norte")-SUMAR.SI.CONJUNTO(D2:D10,A2:A10,"Sur")', '=SUMIFS(D2:D10,A2:A10,"Norte")-SUMIFS(D2:D10,A2:A10,"Sur")', 'I4', 72),
(179, 'Experto 4', 'CONTAR.SI.CONJUNTO', 'Porcentaje filtrado', 'Divide CONTAR.SI.CONJUNTO de D2:D10 mayor que 200 Y E2:E10 mayor que 10 entre CONTAR(D2:D10) en I5.', '=CONTAR.SI.CONJUNTO(D2:D10,">200",E2:E10,">10")/CONTAR(D2:D10)', '=COUNTIFS(D2:D10,">200",E2:E10,">10")/CONTAR(D2:D10)', 'I5', 73),
(180, 'Experto 4', 'SUMAR.SI.CONJUNTO', 'Promedio filtrado manual', 'Divide SUMAR.SI.CONJUNTO de D2:D10 con C2:C10 "Tecnología" entre CONTAR.SI.CONJUNTO de C2:C10 "Tecnología" en I2.', '=SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Tecnología")/CONTAR.SI.CONJUNTO(C2:C10,"Tecnología")', '=SUMIFS(D2:D10,C2:C10,"Tecnología")/COUNTIFS(C2:C10,"Tecnología")', 'I2', 73),

-- ══════════════════════════════════════════════════════
-- MAESTRO (181-200): Escenarios complejos y combinaciones avanzadas
-- ══════════════════════════════════════════════════════

(181, 'Maestro', 'Fórmulas maestras', 'Índice del máximo con error', 'Usa SI.ERROR+INDICE+COINCIDIR para obtener el nombre del producto con mayor precio o "Error" en G2.', '=SI.ERROR(INDICE(B2:B10,COINCIDIR(MAX(D2:D10),D2:D10,0)),"Error")', '=SI.ERROR(INDEX(B2:B10,MATCH(MAX(D2:D10),D2:D10,0)),"Error")', 'G2', 74),
(182, 'Maestro', 'Fórmulas maestras', 'Concatenar resultado', 'Une "El producto " con el INDICE de B2:B10 que coincide con "P400" en A2:A10 y " cuesta " con INDICE de D2:D10 en G3.', '=CONCATENAR("El producto ",INDICE(B2:B10,COINCIDIR("P400",A2:A10,0))," cuesta ",INDICE(D2:D10,COINCIDIR("P400",A2:A10,0)))', '="El producto "&INDICE(B2:B10,COINCIDIR("P400",A2:A10,0))&" cuesta "&INDICE(D2:D10,COINCIDIR("P400",A2:A10,0))||=CONCATENAR("El producto ",INDEX(B2:B10,MATCH("P400",A2:A10,0))," cuesta ",INDEX(D2:D10,MATCH("P400",A2:A10,0)))', 'G3', 74),
(183, 'Maestro', 'Fórmulas maestras', 'Porcentaje de categoría', 'Calcula CONTAR.SI de C2:C10 "Tecnología" dividido entre CONTAR(C2:C10) multiplicado por 100 en G4.', '=CONTAR.SI(C2:C10,"Tecnología")/CONTAR(C2:C10)*100', '=COUNTIF(C2:C10,"Tecnología")/CONTAR(C2:C10)*100', 'G4', 74),
(184, 'Maestro', 'Fórmulas maestras', 'SI.CONJUNTO con cálculo', 'Si PROMEDIO(D2:D10) es mayor que 500 muestra "Premium", si es mayor que 200 muestra "Estándar", si no "Económico" en G5.', '=SI.CONJUNTO(PROMEDIO(D2:D10)>500,"Premium",PROMEDIO(D2:D10)>200,"Estándar",VERDADERO,"Económico")', '=IFS(PROMEDIO(D2:D10)>500,"Premium",PROMEDIO(D2:D10)>200,"Estándar",TRUE,"Económico")||=IFS(AVERAGE(D2:D10)>500,"Premium",AVERAGE(D2:D10)>200,"Estándar",TRUE,"Económico")', 'G5', 75),
(185, 'Maestro', 'Fórmulas maestras', 'Redondeo del promedio filtrado', 'Redondea a 2 decimales el resultado de SUMAR.SI.CONJUNTO de D2:D10 con C2:C10 "Tecnología" entre CONTAR.SI de C2:C10 "Tecnología" en G6.', '=REDONDEAR(SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Tecnología")/CONTAR.SI(C2:C10,"Tecnología"),2)', '=ROUND(SUMIFS(D2:D10,C2:C10,"Tecnología")/COUNTIF(C2:C10,"Tecnología"),2)', 'G6', 75),
(186, 'Maestro', 'Caso real', 'Informe de stock crítico', 'Si CONTAR.SI.CONJUNTO de E2:E10 menor que 15 Y D2:D10 mayor que 300 es mayor que 0, muestra "Alerta stock"; si no "OK" en I2.', '=SI(CONTAR.SI.CONJUNTO(E2:E10,"<15",D2:D10,">300")>0,"Alerta stock","OK")', '=SI(COUNTIFS(E2:E10,"<15",D2:D10,">300")>0,"Alerta stock","OK")', 'I2', 75),
(187, 'Maestro', 'Caso real', 'Margen por categoría', 'Resta SUMAR.SI.CONJUNTO de E2:E10 (costos) con C2:C10 "Accesorios" a SUMAR.SI.CONJUNTO de D2:D10 (precios) con C2:C10 "Accesorios" en I3.', '=SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Accesorios")-SUMAR.SI.CONJUNTO(E2:E10,C2:C10,"Accesorios")', '=SUMIFS(D2:D10,C2:C10,"Accesorios")-SUMIFS(E2:E10,C2:C10,"Accesorios")', 'I3', 76),
(188, 'Maestro', 'Fórmulas maestras', 'Nombre del más barato protegido', 'Usa SI.ERROR+INDICE+COINCIDIR para obtener el nombre del producto con menor stock en E2:E10, o "Sin datos" en I4.', '=SI.ERROR(INDICE(B2:B10,COINCIDIR(MIN(E2:E10),E2:E10,0)),"Sin datos")', '=SI.ERROR(INDEX(B2:B10,MATCH(MIN(E2:E10),E2:E10,0)),"Sin datos")', 'I4', 76),
(189, 'Maestro', 'Caso real', 'Cobertura premium', 'Si SUMAR.SI.CONJUNTO de D2:D10 con D2:D10 mayor que 500 supera 1500, muestra "Cobertura alta"; si no "Aumentar" en I5.', '=SI(SUMAR.SI.CONJUNTO(D2:D10,D2:D10,">500")>1500,"Cobertura alta","Aumentar")', '=SI(SUMIFS(D2:D10,D2:D10,">500")>1500,"Cobertura alta","Aumentar")', 'I5', 76),
(190, 'Maestro', 'Fórmulas maestras', 'Ratio stock-precio', 'Redondea a 2 decimales la división de SUMA(E2:E10) entre SUMA(D2:D10) multiplicado por 100 en G2.', '=REDONDEAR(SUMA(E2:E10)/SUMA(D2:D10)*100,2)', '=ROUND(SUMA(E2:E10)/SUMA(D2:D10)*100,2)||=ROUND(SUM(E2:E10)/SUM(D2:D10)*100,2)', 'G2', 77),
(191, 'Maestro', 'Caso real', 'Clasificación con INDICE', 'Concatena el nombre del producto con mayor stock y ": líder" en G3.', '=CONCATENAR(INDICE(B2:B10,COINCIDIR(MAX(E2:E10),E2:E10,0)),": líder")', '=INDICE(B2:B10,COINCIDIR(MAX(E2:E10),E2:E10,0))&": líder"||=CONCAT(INDEX(B2:B10,MATCH(MAX(E2:E10),E2:E10,0)),": líder")', 'G3', 77),
(192, 'Maestro', 'Fórmulas maestras', 'Diferencia absoluta promedio', 'Calcula ABS de la diferencia entre PROMEDIO(D2:D10) y la mediana de INDICE(D2:D10,5) en G4.', '=ABS(PROMEDIO(D2:D10)-INDICE(D2:D10,5))', '=ABS(AVERAGE(D2:D10)-INDEX(D2:D10,5))', 'G4', 77),
(193, 'Maestro', 'Caso real', 'Verificación completa', 'Si Y(CONTAR.SI(C2:C10,"Tecnología")>=3, SUMAR.SI(C2:C10,"Tecnología",D2:D10)>1000) muestra "Verificado"; si no "Revisar" en G5.', '=SI(Y(CONTAR.SI(C2:C10,"Tecnología")>=3,SUMAR.SI(C2:C10,"Tecnología",D2:D10)>1000),"Verificado","Revisar")', NULL, 'G5', 78),
(194, 'Maestro', 'Fórmulas maestras', 'Peso porcentual', 'Calcula REDONDEAR de SUMAR.SI(C2:C10,"Accesorios",D2:D10)/SUMA(D2:D10)*100 a 1 decimal en G6.', '=REDONDEAR(SUMAR.SI(C2:C10,"Accesorios",D2:D10)/SUMA(D2:D10)*100,1)', '=ROUND(SUMIF(C2:C10,"Accesorios",D2:D10)/SUM(D2:D10)*100,1)', 'G6', 78),
(195, 'Maestro', 'Caso real', 'Resumen ejecutivo', 'Une "Total: " con SUMA(D2:D10) y " | Promedio: " con REDONDEAR(PROMEDIO(D2:D10),0) en I2.', '=CONCATENAR("Total: ",SUMA(D2:D10)," | Promedio: ",REDONDEAR(PROMEDIO(D2:D10),0))', '="Total: "&SUMA(D2:D10)&" | Promedio: "&REDONDEAR(PROMEDIO(D2:D10),0)', 'I2', 78),
(196, 'Maestro', 'Fórmulas maestras', 'Análisis combinado', 'Si REDONDEAR(PROMEDIO.SI(C2:C10,"Tecnología",D2:D10),0) supera 600, muestra "Invertir"; si no "Evaluar" en I3.', '=SI(REDONDEAR(PROMEDIO.SI(C2:C10,"Tecnología",D2:D10),0)>600,"Invertir","Evaluar")', NULL, 'I3', 79),
(197, 'Maestro', 'Caso real', 'Top y bottom', 'Concatena "Mejor: " con INDICE(B2:B10,COINCIDIR(MAX(D2:D10),D2:D10,0)) y " | Peor: " con INDICE(B2:B10,COINCIDIR(MIN(D2:D10),D2:D10,0)) en I4.', '=CONCATENAR("Mejor: ",INDICE(B2:B10,COINCIDIR(MAX(D2:D10),D2:D10,0))," | Peor: ",INDICE(B2:B10,COINCIDIR(MIN(D2:D10),D2:D10,0)))', '="Mejor: "&INDICE(B2:B10,COINCIDIR(MAX(D2:D10),D2:D10,0))&" | Peor: "&INDICE(B2:B10,COINCIDIR(MIN(D2:D10),D2:D10,0))', 'I4', 79),
(198, 'Maestro', 'Caso real', 'Dashboard de zona', 'Si O(CONTAR.SI.CONJUNTO(A2:A10,"Norte",D2:D10,">500")>=2, SUMAR.SI.CONJUNTO(D2:D10,A2:A10,"Norte")>1000) muestra "Zona fuerte"; si no "Zona débil" en I5.', '=SI(O(CONTAR.SI.CONJUNTO(A2:A10,"Norte",D2:D10,">500")>=2,SUMAR.SI.CONJUNTO(D2:D10,A2:A10,"Norte")>1000),"Zona fuerte","Zona débil")', NULL, 'I5', 79),
(199, 'Maestro', 'Fórmulas maestras', 'KPI redondeado', 'Redondea a 1 decimal: (SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Tecnología")-SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Accesorios"))/SUMA(D2:D10)*100 en G2.', '=REDONDEAR((SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Tecnología")-SUMAR.SI.CONJUNTO(D2:D10,C2:C10,"Accesorios"))/SUMA(D2:D10)*100,1)', NULL, 'G2', 80),
(200, 'Maestro', 'Caso real', 'Diagnóstico maestro', 'Si Y(SUMA(D2:D10)>SUMA(E2:E10)*30, PROMEDIO(D2:D10)>300, CONTAR.SI(E2:E10,">20")>=3) muestra "Excelente"; si no "Mejorar" en I2.', '=SI(Y(SUMA(D2:D10)>SUMA(E2:E10)*30,PROMEDIO(D2:D10)>300,CONTAR.SI(E2:E10,">20")>=3),"Excelente","Mejorar")', NULL, 'I2', 80);
